# build-site.R ---------------------------------------------------------------
# Build the pkgdown site into docs/ and apply the repository's cleanup policy
# (no llms.txt and no "Generated by pkgdown" HTML comments).
# Usage (from the package root): Rscript tools/build-site.R
# ---------------------------------------------------------------------------

options(device = function(...) grDevices::pdf(file = NULL))

pkgdown::build_site(preview = FALSE)

# Ensure llms.txt and companion .md files are absent (also disabled via
# llm-docs: false in _pkgdown.yml).
llms <- file.path("docs", "llms.txt")
if (file.exists(llms)) unlink(llms)

# Strip generator comments from all built HTML files.
html_files <- list.files("docs", pattern = "[.]html$", recursive = TRUE, full.names = TRUE)
marker <- "<!-- Generated by pkgdown: do not edit by hand -->"
n_cleaned <- 0L
for (f in html_files) {
  txt <- readLines(f, warn = FALSE, encoding = "UTF-8")
  if (any(grepl(marker, txt, fixed = TRUE))) {
    txt <- gsub(marker, "", txt, fixed = TRUE)
    writeLines(txt, f, useBytes = FALSE)
    n_cleaned <- n_cleaned + 1L
  }
}

cat(sprintf(
  "Site built in docs/: %d HTML files (%d cleaned of generator comments); llms.txt exists: %s\n",
  length(html_files), n_cleaned, file.exists(llms)
))
